#!/usr/bin/env python3
"""Maintained Cinomi legal/support pages. Run from any directory; no analytics on legal pages."""
from pathlib import Path
import html,re
root=Path(__file__).resolve().parents[1]
base='https://justcompress.online/apps/cinomi'
sections={
'privacy': [('English',[
('Privacy Policy — Cinomi','Cinomi — Cinema & Showtimes is provided by Space Sheep Studio. Updated November 17, 2026.'),
('Location and local preferences','Device location is used on your device to suggest a nearby connected city and calculate cinema distances. Precise GPS coordinates are not sent for schedule searches. City selection, language, taste preferences and saved films are stored on your device. The app does not require a Cinomi account.'),
('Schedule and film requests','The selected city or its public centre coordinates, country and screening date are sent to our backend and schedule providers. Film metadata requests may include the title, original title, release date, director, runtime, public poster URL and IMDb/TMDB identifier. These requests support matching films across languages and showing ratings. Your full taste profile and watchlist are not uploaded as a profile.'),
('Services and technical data','Services include AlloCiné, paris-cine.info, Filmstarts, SensaCine, Forum Cinemas Latvia, Sambíóin, Apollo Kino, Cineplexx, Cinema City, Ciné Bruxelles, TMDB and OMDb. International Showtimes may be used where configured. Posters, trailers and booking pages may load from their respective providers. Network services may receive IP addresses and technical request data and maintain operational logs under their own policies. Schedule and film metadata may be cached to improve speed and availability; this is not a promise that all network activity stays on your device.'),
('Purchases and optional advertising','Apple processes Cinomi Pro purchases and subscriptions; we do not receive payment-card details. Advertising availability depends on the installed version. If a version enables Google AdMob, free users may see ads and AdMob may process identifiers, IP addresses, approximate location and ad interactions. Versions with advertising disabled do not start the ad SDK. Where required, the app requests ad consent before ads and tracking permission before IDFA access; the ad SDK is not started for verified subscribers at launch, and new ad requests and placements stop if a user subscribes during a session. Ad consent choices can be changed in Settings where required. Declining consent or unavailable ads never prevents use of cinema and film features.'),
('Retention and choices','Local preferences and saved films remain until you remove them or delete the app. Device backups may retain app data according to your system settings. You can refuse location permission and select a city manually, manage notifications in system settings, and manage subscriptions through Apple. The app is not designed for children under 13. Contact Space Sheep Studio at liang.laurie@gmail.com for privacy questions.')]),
('Français',[
('Confidentialité — Cinomi','Cinomi — Cinema & Showtimes est proposé par Space Sheep Studio. Mise à jour : 17 novembre 2026.'),
('Localisation et données locales','La position précise sert sur votre appareil à proposer une ville connectée et calculer les distances. Elle n’est pas transmise pour rechercher les séances. La ville, la langue, les préférences et les films enregistrés sont stockés localement. Aucun compte Cinomi n’est requis.'),
('Requêtes et prestataires','La ville ou ses coordonnées centrales publiques, le pays et la date sont transmis au serveur et aux fournisseurs de séances. Les requêtes de films peuvent inclure titre, titre original, date, réalisateur, durée, affiche publique et identifiants IMDb/TMDB. Le profil de goûts et la liste complète ne sont pas envoyés comme profil. Les services cités dans la section anglaise fournissent séances, métadonnées, affiches, bandes-annonces et réservation. Les services réseau peuvent recevoir l’adresse IP et des données techniques, conserver des journaux et mettre en cache les données de films et séances.'),
('Achats et publicité éventuelle','Apple traite les achats et abonnements Cinomi Pro, sans nous transmettre les données de carte. La publicité dépend de la version installée. Si AdMob est activé, il peut traiter identifiants, adresse IP, position approximative et interactions publicitaires. Le SDK ne démarre pas lorsque les annonces sont désactivées ou pour les abonnés vérifiés au lancement. Un abonnement souscrit en cours de session arrête les nouvelles demandes et retire les annonces. Les choix publicitaires sont accessibles dans Réglages lorsque requis. Un refus de consentement ou une publicité indisponible ne bloque aucune fonction cinéma. Le consentement publicitaire et l’autorisation IDFA sont demandés lorsque requis.'),
('Vos choix','Les préférences restent sur l’appareil jusqu’à leur suppression ; les sauvegardes dépendent du système. Vous pouvez refuser la localisation, choisir une ville manuellement et gérer notifications et abonnements dans les réglages système/Apple. L’app n’est pas destinée aux moins de 13 ans. Contact : Space Sheep Studio, liang.laurie@gmail.com.')]),
('中文',[
('Cinomi 隐私政策','Cinomi — Cinema & Showtimes 由 Space Sheep Studio 提供。更新日期：2026 年 11 月 17 日。'),
('定位与本地数据','设备精确位置仅在设备上用于建议附近已接入城市和计算影院距离，不用于向排片服务器发送精确 GPS 坐标。城市、语言、偏好和收藏保存在设备上，无需 Cinomi 账号。'),
('网络请求与服务商','所选城市或公开市中心坐标、国家和场次日期会发送至后端及排片服务商。影片匹配请求可包含片名、原名、发行日期、导演、时长、公开海报链接和 IMDb/TMDB 编号，不会将完整口味或收藏列表作为个人资料上传。英文部分所列服务商提供排片、影片资料、评分、海报、预告与订票服务。网络服务可能接收 IP 地址及技术请求数据，并按各自政策保留运行日志；排片和影片资料可能被缓存。'),
('购买与可选广告','Apple 处理 Cinomi Pro 购买与订阅，我们不会获得银行卡信息。是否展示广告取决于所安装版本。启用 AdMob 时，免费用户可能看到广告，服务商可能处理标识符、IP、粗略位置和广告互动数据。关闭广告的版本及启动时已验证订阅的用户不会启动广告 SDK；使用途中订阅会停止新广告请求并移除广告，拒绝广告同意或无广告可展示不影响电影功能，在适用地区可从设置调整广告隐私选择；在适用地区会先请求广告同意，访问 IDFA 前会请求跟踪权限。'),
('保留与选择','本地偏好和收藏保留至你主动删除或卸载，系统备份按设备设置处理。你可拒绝定位后手动选城，并在系统设置中管理通知、在 Apple 中管理订阅。本应用不面向 13 岁以下儿童。隐私联系：Space Sheep Studio，liang.laurie@gmail.com。')])],
'support': [('English',[
('Cinomi Support','Cinomi — Cinema & Showtimes, by Space Sheep Studio.'),
('Cities, times and languages','Select a city or use device location. Only connected nearby cities are selected automatically; other cities can be checked manually. Times follow the selected city’s time zone. Coverage is partial: not every cinema is included. Audio not specified means the cinema source did not publish the screening language.'),
('Refresh and booking','If a refresh fails, saved same-city/date schedules may remain visible with a timestamp. Retry and confirm details on the cinema’s official site before travelling. Some booking links open a cinema page where you must choose the matching film, date and time.'),
('Pro and contact','From version 1.7.0 every feature is free; Pro only removes ads. For purchase issues, use Restore Purchases in the app and check your Apple subscription settings. Do not send payment-card details. For help, email liang.laurie@gmail.com with your city, app version and a description; a screenshot is optional. Do not send passwords, API keys or precise home location.')]),
('Français',[
('Assistance Cinomi','Choisissez une ville ou utilisez la localisation. Les heures suivent le fuseau de la ville choisie ; la couverture reste partielle. Une langue non précisée n’a pas été fournie par le cinéma.'),
('Actualisation et réservation','Les séances enregistrées peuvent rester visibles avec leur date de mise à jour si le réseau échoue. Réessayez et vérifiez auprès du cinéma. Certains liens ouvrent la page du cinéma : choisissez alors le film, la date et l’heure. Depuis la version 1.7.0, toutes les fonctions sont gratuites ; Pro retire uniquement les publicités. Pour un achat, utilisez Restaurer les achats et les réglages Apple. Contact : Space Sheep Studio, liang.laurie@gmail.com ; indiquez la ville et la version sans données de paiement ni mot de passe.')]),
('中文',[
('Cinomi 支持','手动选择城市或使用定位，时间按所选城市时区显示。仅覆盖部分影院；“语言未注明”表示源影院没有提供该场次语言。'),
('刷新、订票与购买','网络失败时可能继续显示带时间的已保存场次，请重试并在出发前向影院确认。有些订票链接会打开影院主页，需要自行选片、选日期和时间。自 1.7.0 起所有功能免费，Pro 仅去除广告。购买问题可使用应用内“恢复购买”和 Apple 订阅设置。联系 Space Sheep Studio：liang.laurie@gmail.com，请说明城市、应用版本和问题，不要发送密码、支付资料或精确家庭住址。')])],
'terms': [('English',[
('Cinomi Terms of Use','Cinomi — Cinema & Showtimes is provided by Space Sheep Studio. Updated November 17, 2026. The iOS app uses Apple’s Standard Licensed Application End User License Agreement (EULA), linked below.'),
('Schedules and external booking','Schedules, availability, ratings, language and format information come from third parties and may change or be incomplete. Confirm details with the cinema. Cinomi does not sell cinema tickets; the cinema or booking service handles ticket purchases, refunds and its own terms.'),
('Cinomi Pro subscriptions','From version 1.7.0, all cinema and film features are free with advertising. Cinomi Pro removes in-app advertising only; it does not unlock extra features. Earlier versions may offer different feature access. Pro is offered as monthly and yearly auto-renewable subscriptions. The app shows the available plan, duration, benefits and localized total charge before purchase. Payment is charged to your Apple Account. Subscriptions renew unless cancelled at least 24 hours before the current period ends. Manage or cancel through Apple’s subscription settings; cancellation stops future renewals and access normally continues through the paid period. Restore Purchases is available in the app. Introductory offers, if displayed, depend on Apple eligibility. We do not promise complete European cinema coverage.'),
('Contact','Questions: Space Sheep Studio, liang.laurie@gmail.com. Mandatory consumer rights and the terms governing Apple purchases continue to apply.')]),
('Français',[
('Conditions d’utilisation — Cinomi','L’app iOS est régie par le contrat de licence standard Apple (lien ci-dessous). Les séances et informations tierces peuvent changer ou être incomplètes ; vérifiez auprès du cinéma. Les billets, remboursements et conditions de réservation relèvent du vendeur externe.'),
('Abonnements Cinomi Pro','À partir de la version 1.7.0, toutes les fonctions cinéma et films sont gratuites avec publicité. Cinomi Pro retire uniquement les publicités, sans fonction supplémentaire. Les versions antérieures peuvent différer. Des abonnements mensuels et annuels à renouvellement automatique sont proposés. L’écran d’achat indique durée, avantages et montant localisé total. Apple facture votre compte ; annulez au moins 24 heures avant la fin de la période pour éviter le prochain renouvellement. Gérez l’abonnement dans les réglages Apple et restaurez les achats dans l’app. Les droits impératifs des consommateurs restent applicables. Contact : Space Sheep Studio, liang.laurie@gmail.com.')]),
('中文',[
('Cinomi 使用条款','iOS 应用适用下方 Apple 标准最终用户许可协议。第三方排片和资料可能变动或不完整，请向影院确认。Cinomi 不销售电影票，票务购买、退款和相关条款由外部影院或票务服务商处理。'),
('Cinomi Pro 订阅','自 1.7.0 起，所有影院和电影功能免费开放并可能展示广告，Cinomi Pro 仅去除应用内广告，不锁定额外功能。旧版本的功能权益可能不同。提供按月及按年自动续订方案，购买前显示具体周期、权益和本地化总费用，由 Apple 账户付款。若不希望续订，请至少在当前周期结束 24 小时前取消；可在 Apple 订阅设置管理，并在应用内恢复购买。取消通常停止后续续费，已付费周期内继续享有权益。优惠取决于 Apple 资格条件；不承诺欧洲所有影院完整覆盖。法定消费者权利继续适用。联系 Space Sheep Studio：liang.laurie@gmail.com。')])]
}
for page, languages in sections.items():
 title={'privacy':'Privacy Policy','support':'Support','terms':'Terms of Use'}[page]
 content=[]
 for language,blocks in languages:
  content.append(f'<section><h2>{html.escape(language)}</h2>')
  for heading,body in blocks:content.append(f'<h3>{html.escape(heading)}</h3><p>{html.escape(body)}</p>')
  content.append('</section>')
 links=' · '.join(f'<a href="{base}/{slug}/">{label}</a>' for slug,label in [('privacy','Privacy'),('support','Support'),('terms','Terms')])
 output=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cinomi — {title}</title><link rel="canonical" href="{base}/{page}/"><meta name="description" content="{title} for Cinomi — Cinema &amp; Showtimes, provided by Space Sheep Studio."><style>body{{font:16px/1.65 system-ui,sans-serif;max-width:780px;margin:auto;padding:28px 20px;background:#071313;color:#e6f5f2}}a{{color:#61deca}}h1,h2,h3{{line-height:1.25}}h2{{margin-top:2em;color:#61deca}}h3{{font-size:1.1em}}p{{color:#c1d4d0}}nav,footer{{font-size:.9em}}section{{border-top:1px solid #28443f;margin-top:2em}}a:focus{{outline:2px solid #61deca}}</style></head><body><nav><a href="https://paris-cine.vercel.app">Cinomi</a> · {links}</nav><h1>Cinomi — {title}</h1>{''.join(content)}<p><a href="https://www.apple.com/legal/internet-services/itunes/dev/stdeula/">Apple Standard EULA</a> · <a href="https://apps.apple.com/account/subscriptions">Manage Apple subscriptions</a></p><footer>© 2026 Space Sheep Studio · {links}</footer></body></html>'''
 assert not re.search(r'jiali\s+liang',output,re.I)
 directory=root/'apps'/'cinomi'/page;directory.mkdir(parents=True,exist_ok=True)
 (directory/'index.html').write_text(output)
print('Generated three Cinomi pages; legal pages remain excluded from website analytics.')
